(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const dataset=window.PERSON_BIOGRAPHIES||{people:{},recordToPerson:{}};
 function get(id){return dataset.people[dataset.recordToPerson[id]||id]||null;}
 function textOf(p){const b=get(p.id);return b?[b.name,b.lead,...b.periods.map(x=>[x.period,x.title,x.body].join(' ')),...b.relationships.map(x=>[x.name,x.relation,x.details].join(' '))].join(' '):'';}
 function refLine(refs,p){if(!refs?.length)return '';const b=get(p.id);return `<div class="biography-evidence">材料：${refs.map(r=>{const books=[...r.matchAll(/《([^》]+)》/g)].map(m=>m[1]);const tags=r.match(/(?:[A-Z]{1,4}-(?:ST-)?\d+|\d{1,2}-\d{1,2})/g)||[];const clean=s=>s.replace(/[\s·]/g,'');const sameBook=s=>books.some(t=>s.label.includes('《'+t+'》'));const source=b?.sources.find(s=>clean(s.label)===clean(r)||clean(s.label).includes(clean(r)))||b?.sources.find(s=>sameBook(s)&&tags.some(t=>new RegExp(t+'(?![0-9-])').test(s.label)))||b?.sources.find(sameBook)||b?.sources.find(s=>r.includes(s.label));return `<a href="${esc(source?.url||p.source)}" target="_blank" rel="noopener noreferrer">${esc(r)} ↗</a>`;}).join('；')}</div>`;}
 function toc(p){const b=get(p.id);if(!b)return '';return `<aside class="biography-toc"><div class="eyebrow">LIFE & EVENTS</div><p class="toc-name">${esc(b.name)} · 人物纪事</p>${window.PROFILE_UI?.get(p.id)?'<a href="#operator-dossier" data-anchor="operator-dossier">干员档案</a>':''}${b.periods.map((x,i)=>`<a href="#life-${i}" data-anchor="life-${i}"><small>${String(i+1).padStart(2,'0')} / ${esc(x.period)}</small>${esc(x.title)}</a>`).join('')}${window.JOURNEY_UI?.get(p).length?'<a href="#life-journey" data-anchor="life-journey">设定集补记</a>':''}<a href="#life-relations" data-anchor="life-relations">人物关系</a><a href="#life-evidence" data-anchor="life-evidence">资料与时序说明</a></aside>`;}
 function inlineToc(p){const b=get(p.id);if(!b)return '';return `<details class="biography-mobile-toc"><summary>本篇目录 · ${b.periods.length} 个阶段</summary>${window.PROFILE_UI?.get(p.id)?'<a href="#operator-dossier" data-anchor="operator-dossier">干员档案</a>':''}${b.periods.map((x,i)=>`<a href="#life-${i}" data-anchor="life-${i}">${esc(x.period)} · ${esc(x.title)}</a>`).join('')}${window.JOURNEY_UI?.get(p).length?'<a href="#life-journey" data-anchor="life-journey">设定集补记</a>':''}<a href="#life-relations" data-anchor="life-relations">人物关系</a></details>`;}
 function render(p,byName){const b=get(p.id);if(!b)return `<section class="chapter-section"><h2>${esc(p.title)}</h2><p>${esc(p.summary)}</p></section><div class="reflection"><span>资料范围</span>${esc(p.focus)}</div>`;
 const count=b.lead.length+b.periods.reduce((n,x)=>n+x.body.length,0)+b.relationships.reduce((n,x)=>n+x.details.length,0);
 return `<div class="biography-intro"><div class="meta">人物纪事 · 约 ${Math.max(2,Math.ceil(count/350))} 分钟 · ${b.periods.length} 个阶段</div><p>${esc(b.lead)}</p>${b.recordIds.length>1?`<div class="biography-stage-note">本页以“${esc(p.name)}”为入口，以下将${esc(b.name)}及其关联形态的已知经历合并叙述；具体阶段、分支和资料时点分别标明。</div>`:''}</div>${inlineToc(p)}<div class="life-timeline">${b.periods.map((x,i)=>`<section class="life-period chapter-section" id="life-${i}"><div class="period-label"><span>${String(i+1).padStart(2,'0')}</span>${esc(x.period)}</div><h2>${esc(x.title)}</h2>${x.body.split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}${refLine(x.refs,p)}${window.REGION_UI.periodLinks(p,x)}</section>`).join('')}</div>${window.JOURNEY_UI?.render(p)||''}<section class="biography-relations" id="life-relations"><div class="eyebrow">PEOPLE & RELATIONSHIPS</div><h2>人物关系与变化</h2>${b.relationships.length?`<div class="relationship-list">${b.relationships.map(x=>{const target=byName(x.name);return `<article class="relationship-card"><div class="relation-heading">${target?`<a href="#/character/${target.id}">${esc(x.name)} ↗</a>`:`<strong>${esc(x.name)}</strong>`}<span>${esc(x.relation)}</span></div><p>${esc(x.details)}</p>${refLine(x.refs,p)}</article>`;}).join('')}</div>`:'<p class="limited-material">现有材料不足以确认可单列的主要个人关系。本篇不从同场出勤、医疗签名或玩法编组推定亲密关系。</p>'}</section><section class="biography-sources" id="life-evidence"><h2>资料与时序说明</h2><p>${esc(b.chronologyNote)}</p><ol>${b.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a></li>`).join('')}</ol><p class="limited-material">年份缺失时按资料可确认的相对阶段排列；没有把档案解锁顺序、密录上线时间或活动发布日期直接当作故事发生日期。人物动机仅限材料明确交代的内容。</p></section>`;
 }
 window.BIOGRAPHY_UI={get,textOf,toc,render};
})();
